-- Catalogo de Ultra Hardware para Supabase
-- Generado a partir del index.html original (152 productos).
--
-- COMO USARLO
--   1. Entrar al proyecto en https://supabase.com
--   2. Ir a "SQL Editor" > "New query"
--   3. Pegar todo este archivo y ejecutar (Run)
--
-- Si la tabla ya tenia productos de prueba, revisar el DELETE comentado
-- mas abajo antes de ejecutar el INSERT.

-- Columnas nuevas que usa la pagina para mostrar descripcion y enlace al detalle
alter table public.productos add column if not exists descripcion text;
alter table public.productos add column if not exists ancla text;

-- Limpieza de las filas de prueba que existian antes de la migracion.
-- Si ya ejecutaste este archivo, esta linea no hace nada.
delete from public.productos
where nombre in ('Nombre del producto 2', 'Nombre del producto 3')
   or (nombre = 'Monitor Samsung 24" 75Hz' and ancla is null);

-- Si queres arrancar la tabla de cero, descomenta esta linea:
-- delete from public.productos;

on conflict do nothing;
